---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Event calendar: A week view where the agent finds a free slot for you.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change event-calendar.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './event-calendar.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'wide', className]} data-c="event-calendar" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="ecx panel">
  <div class="ecx-h"><b>Oct 19 – 23, 2026</b><span class="ecx-sp"></span><span class="ecx-msg muted"></span><button class="pill soft sm ecx-ask"><svg class="i xs"><use href="#i-spark"/></svg>Find 45 min for a design review</button></div>
  <div class="ecx-days" role="group" aria-label="Day"></div>
  <div class="ecx-sc"><div class="ecx-grid"><div class="ecx-tm"></div></div></div>
</div>
  </Fragment></div>
</div>
<script>
  import './event-calendar.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Event calendar ---------- */
.ecx{overflow:hidden;position:relative;container:ecx/inline-size}
/* the Ask pill crossfades its words but stays a flex row, so the spark keeps its gap */
.ecx-ask.sw{display:inline-flex}
/* the Ask pill is an accent tint, like a picked preset in Date range picker */
.pill.soft.ecx-ask{background:var(--dm-sel);color:var(--dm-accent-fg,var(--dm-accent));box-shadow:none}
@media (hover:hover) and (pointer:fine){.pill.soft.ecx-ask:hover{background:color-mix(in srgb,var(--dm-accent) 14%,transparent)}}
.ecx-h{display:flex;align-items:center;gap:var(--dm-s-2);padding:10px var(--dm-s-3);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13.5px;flex-wrap:wrap}
.ecx-h b{font-weight:500}
.ecx-sp{flex:1}
.ecx-sc{overflow-x:auto}
/* --dm-ph is the height of an hour: every event, the grid lines and the time column are laid out in hours of it */
.ecx-grid{display:grid;grid-template-columns:44px repeat(var(--dm-days,5),minmax(76px,1fr));min-width:424px;position:relative;--dm-ph:44px}
.ecx-tm{grid-row:1/3;display:flex;flex-direction:column;padding-top:var(--dm-s-8)}
.ecx-tm span{height:var(--dm-ph);font-size:10.5px;color:var(--dm-muted);text-align:right;padding-right:var(--dm-s-2);transform:translateY(-6px)}
.ecx-tm i{font-style:normal}
/* the time column reads in hours (9am), and in half hours (9:00, 9:30) where one row is 30 minutes */
.ecx-tm .hf,.ecx-tm .n{display:none}
.ecx-day{border-left:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.ecx-dh{height:32px;display:flex;align-items:center;justify-content:center;gap:5px;font-size:12px;color:var(--dm-fg2);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.ecx-dh b{font-weight:500;color:var(--dm-fg)}
.ecx-dh.t b{width:22px;height:22px;border-radius:50%;background:var(--dm-accent);color:var(--dm-on-accent);display:grid;place-items:center;font-size:11.5px}
.ecx-col{position:relative;height:calc(var(--dm-ph) * 8);background-image:linear-gradient(color-mix(in srgb,var(--dm-line) 50%,transparent) 1px,transparent 1px);background-size:100% var(--dm-ph)}
.ecx-e{position:absolute;left:3px;right:3px;border-radius:var(--dm-r-sm);padding:var(--dm-s-1) 7px;font-size:11.5px;line-height:1.3;text-align:left;overflow:hidden;transition:transform .25s var(--dm-ease),box-shadow .25s}
@media (hover:hover) and (pointer:fine){.ecx-e:hover{transform:translateY(-1px);box-shadow:var(--dm-shadow)}}
/* events sit in the scrolling grid, which would cut an outside ring: theirs is drawn inside */
.ecx-e:focus-visible{outline-offset:-2px}
.ecx-e{cursor:grab;touch-action:none}
.ecx-e.drag{transition:none;z-index:6;box-shadow:var(--dm-shadow-pop);cursor:grabbing}
.ecx-col{cursor:copy}
.ecx-ghost{position:absolute;left:3px;right:3px;height:calc(var(--dm-ph) - 3px);border-radius:var(--dm-r-sm);border:1.5px dashed color-mix(in srgb,var(--dm-accent-mark,var(--dm-accent)) 45%,transparent);background:color-mix(in srgb,var(--dm-accent) 5%,transparent);color:var(--dm-accent-fg,var(--dm-accent));font-size:11px;font-weight:500;padding:var(--dm-s-1) 7px;pointer-events:none}
.ecx-now{position:absolute;left:0;right:0;height:2px;margin-top:-1px;background:var(--dm-bad-mark);z-index:3}
.ecx-now::before{content:"";position:absolute;left:-4px;top:-3px;width:8px;height:8px;border-radius:50%;background:var(--dm-bad-mark)}
.ecx-msg{font-size:12.5px;margin-right:var(--dm-s-2)}
.ecx-pop{position:absolute;z-index:20;width:248px;padding:var(--dm-s-3);background:var(--dm-raised);border-radius:calc(14px * var(--dm-rk));box-shadow:var(--dm-shadow-pop);opacity:0;visibility:hidden;transform:translateY(6px);filter:blur(3px);pointer-events:none;transition:opacity .2s var(--dm-ease),transform .35s var(--dm-ease),filter .2s,visibility 0s .2s}
.ecx-pop.open{opacity:1;visibility:visible;transform:none;filter:none;pointer-events:auto;transition-property:opacity,transform,filter}
.ecx-ph{display:flex;align-items:center;gap:var(--dm-s-2);font-size:13.5px}
.ecx-ph>i{width:10px;height:10px;border-radius:3px;flex:none}
.ecx-ph b{font-weight:500;flex:1;min-width:0}
.ecx-ph .ib{width:24px;height:24px;margin:-4px -4px -4px auto}
/* a new event's title is a field like any other: white, the dimmed field edge, one step stronger while you type */
.ecx-ti{flex:1;min-width:0;height:32px;padding:0 var(--dm-s-3);border:0;outline:0;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);font:inherit;font-weight:500;color:var(--dm-fg);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.ecx-ti{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.ecx-ti::placeholder{color:var(--dm-muted)}
.ecx-ti:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.ecx-pt{font-size:12.5px;color:var(--dm-fg2);margin:var(--dm-s-1) 0 0 18px}
.ecx-pw{display:flex;align-items:center;margin:10px 0 0 18px}
.ecx-pw .av{width:22px;height:22px;font-size:9px;margin-right:-4px;box-shadow:0 0 0 2px var(--dm-raised)}
.ecx-pw .muted{margin-left:10px;font-size:12px}
.ecx-note{display:flex;gap:6px;align-items:flex-start;margin:10px 0 0 18px;font-size:12px;line-height:1.45;color:var(--dm-fg2)}
.ecx-note .i{color:var(--dm-accent-fg,var(--dm-accent));margin-top:2px}
.ecx-pa{display:flex;justify-content:flex-end;gap:6px;margin-top:var(--dm-s-3)}
.ecx-e b{display:block;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ecx-e span{font-size:10.5px}
.ecx-e.sug{background:var(--dm-surface)!important;color:var(--dm-accent-fg,var(--dm-accent))!important;box-shadow:inset 0 0 0 1.5px var(--dm-accent-mark,var(--dm-accent));animation:ecs .6s var(--dm-ease) both}
.ecx-e.sug.alt{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-accent-mark,var(--dm-accent)) 40%,transparent)}
@keyframes ecs{from{opacity:0;transform:scale(.92);filter:blur(3px)}}
.ecx-sg{display:flex;gap:var(--dm-s-1);margin-top:var(--dm-s-1)}
.ecx-sg button{font-size:10.5px;padding:2px 6px;border-radius:5px;background:var(--dm-accent);color:var(--dm-on-accent)}
.ecx-sg button.n{background:transparent;color:var(--dm-accent-fg,var(--dm-accent))}
.ecx-scan{position:absolute;left:44px;right:0;height:2px;background:linear-gradient(90deg,transparent,var(--dm-accent),transparent);top:32px;opacity:0;pointer-events:none}
.ecx-scan.go{animation:ecsc 1.2s var(--dm-ease-io) both}
@keyframes ecsc{0%{opacity:0;top:32px}20%{opacity:1}100%{opacity:0;top:384px}}
/* a narrow calendar, on a phone or in a narrow card: one day at a time, picked from a row of days, so every event has room
   for its whole title and time. Each row of the grid is half an hour (owner, 4 Nov): an hour is two rows, so an event from
   9 to 10 is two rows tall, and the time column reads 9:00, 9:30, 10:00 */
.ecx-days{display:none}
@container ecx (max-width:519px){
  .ecx-days{display:flex;gap:var(--dm-s-1);padding:var(--dm-s-2) var(--dm-s-3);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
  .ecx-days button{flex:1;min-width:0;display:flex;flex-direction:column;align-items:center;gap:2px;padding:var(--dm-s-1) 0;border-radius:var(--dm-r-sm);font-size:11.5px;color:var(--dm-fg2);transition:background var(--dm-t-fast),color var(--dm-t-fast)}
  @media (hover:hover) and (pointer:fine){.ecx-days button:hover{background:var(--dm-row);color:var(--dm-fg)}}
  .ecx-days button[aria-pressed="true"]{background:var(--dm-surface);color:var(--dm-fg);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-on) 50%,transparent)}
  .ecx-days b{display:grid;place-items:center;width:24px;height:24px;border-radius:50%;font-size:13px;font-weight:500;color:var(--dm-fg)}
  .ecx-days .t b{background:var(--dm-accent);color:var(--dm-on-accent)}
  .ecx-sc{overflow:visible}
  .ecx-grid{grid-template-columns:44px minmax(0,1fr);min-width:0;padding-top:var(--dm-s-2);--dm-ph:56px}
  .ecx-col{background-size:100% calc(var(--dm-ph) / 2)}
  .ecx-tm span{height:calc(var(--dm-ph) / 2)}
  .ecx-tm .hf,.ecx-tm .n{display:block}
  .ecx-tm .w{display:none}
  .ecx-day:not(.on){display:none}
  .ecx-dh{display:none}
  .ecx-tm{grid-row:auto;padding-top:0}
  .ecx-scan{top:8px}
  .ecx-scan.go{animation-name:ecscn}
  .ecx-pop{max-width:calc(100% - 16px)}
}
@keyframes ecscn{0%{opacity:0;top:8px}20%{opacity:1}100%{opacity:0;top:calc(var(--dm-ph) * 8 + 8px)}}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, AV, DM, I, enter, hideTip, html, openPop, swap } from '../core/core.js';
DM.def('event-calendar', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{spark}', I('spark','xs'));
  const DAYS = ['Mon 19','Tue 20','Wed 21','Thu 22','Fri 23'], H0 = 9;
  const EV = [[0,9,1,'Standup','b'],[0,13,1.5,'Pricing workshop','p'],[1,10,1,'1:1 with Maya','l'],[1,14,2,'Focus: checkout','t'],[2,9,1,'Standup','b'],[2,11.5,1,'Agent demo','y'],[3,9,1,'Standup','b'],[3,12,1,'Lunch & learn','m'],[3,15,1.5,'Launch review','r'],[4,10,1.5,'Planning','p']];
  const grid = $('.ecx-grid', r);
  // an hour's height (--ph): 44px, or 56px on a narrow calendar where each 28px row is half an hour. Places are written in it,
  // so events keep their times when the calendar narrows or widens
  const PX = () => parseFloat(getComputedStyle(grid).getPropertyValue('--dm-ph')) || 44, at = h => `calc(var(--dm-ph) * ${h - H0} + 1px)`, tall = n => `calc(var(--dm-ph) * ${n} - 3px)`;
  // the time column: an hour a row (9am), or on a narrow calendar half an hour a row (9:00, 9:30)
  $('.ecx-tm', r).innerHTML = Array.from({ length:16 }, (_, i) => { const h = H0 + Math.floor(i / 2), h12 = h > 12 ? h - 12 : h; return i % 2 ? `<span class="hf"><i class="n">${h12}:30</i></span>` : `<span><i class="w">${h12}${h >= 12 ? 'pm' : 'am'}</i><i class="n">${h12}:00</i></span>`; }).join('');
  grid.insertAdjacentHTML('beforeend', DAYS.map((d, i) => `<div class="ecx-day"><div class="ecx-dh${i === 0 ? ' t' : ''}">${d.split(' ')[0]} <b>${d.split(' ')[1]}</b></div><div class="ecx-col" data-d="${i}"></div></div>`).join('') + '<div class="ecx-scan"></div>');
  const col = i => $(`.ecx-col[data-d="${i}"]`, grid);
  /* a narrow calendar shows one day: the row of days picks it, and an answer from the agent opens the day it found */
  const days = $('.ecx-days', r);
  days.innerHTML = DAYS.map((d, i) => `<button aria-pressed="false" data-d="${i}"${i === 0 ? ' class="t"' : ''} aria-label="${['Monday','Tuesday','Wednesday','Thursday','Friday'][i]} ${d.split(' ')[1]} October"><span>${d.split(' ')[0]}</span><b>${d.split(' ')[1]}</b></button>`).join('');
  let day = -1;
  const narrow = () => !!days.getClientRects().length;
  function showDay(i){
    if (i === day) return; const was = day; day = i;
    $$('button', days).forEach(b => b.setAttribute('aria-pressed', +b.dataset.d === i));
    $$('.ecx-day', grid).forEach((d, k) => d.classList.toggle('on', k === i));
    if (was >= 0 && narrow()){ closePop(); enter(col(i).parentElement); }
  }
  $$('button', days).forEach(b => b.onclick = () => showDay(+b.dataset.d));
  const tm = h => { const hh = Math.floor(h), mm = Math.round((h - hh) * 60); return `${hh > 12 ? hh - 12 : hh}:${String(mm).padStart(2, '0')}`; };
  const ev = (e, cls = '') => html(`<button class="ecx-e ${cls}" style="top:${at(e[1])};height:${tall(e[2])};background:var(--dm-p${e[4]}-bg);color:var(--dm-p${e[4]})"><b>${e[3]}</b><span>${tm(e[1])} – ${tm(e[1] + e[2])}</span></button>`);
  const panel = $('.ecx', r), msg = $('.ecx-msg', r), pop = html('<div class="ecx-pop" role="dialog" aria-label="Event"></div>'); panel.appendChild(pop);
  const WHO = [['MK','var(--dm-av-l)'],['JO','var(--dm-av-m)'],['DA','var(--dm-av-b)'],['AR','var(--dm-av-p)']], DAYN = ['Mon','Tue','Wed','Thu','Fri'];
  let openFor = null;
  const say = t => swap(msg, t);
  // closing gives the focus back to the event when it was in the card
  const closePop = () => { const back = pop.contains(document.activeElement) && openFor; pop.classList.remove('open'); openFor = null; if (back && back.isConnected) back.focus({ preventScroll:true }); };
  /* the details card opens beside the event and stays inside the calendar */
  function openPop(el){
    const e = el._e; if (openFor === el){ closePop(); return; } openFor = el; const n = 2 + e[3].length % 3, fresh = e[3] === 'New event';
    pop.innerHTML = `<div class="ecx-ph"><i style="background:var(--dm-p${e[4]})"></i>${fresh ? '<input class="ecx-ti" placeholder="Add a title" aria-label="Event title">' : `<b>${e[3]}</b>`}<button class="ib ecx-px" aria-label="Close" data-tip="Close">${I('x','xs')}</button></div><div class="ecx-pt">${DAYN[e[0]]} ${DAYS[e[0]].split(' ')[1]} Oct · ${tm(e[1])} – ${tm(e[1] + e[2])}</div><div class="ecx-pw">${WHO.slice(0, n).map(w => AV(w[0], w[1])).join('')}<span class="muted">${n} people</span></div><div class="ecx-pa">${fresh ? '<button class="pill ghost sm ecx-del">Discard</button><button class="pill primary sm ecx-save">Save</button>' : `<button class="pill soft sm ecx-prep">${I('spark','xs')}Prep notes</button><button class="pill primary sm">Join</button>`}</div>`;
    const pr = panel.getBoundingClientRect(), er = el.getBoundingClientRect(), w = 248;
    let x = er.right - pr.left + 8; if (x + w > pr.width - 8) x = er.left - pr.left - w - 8; x = Math.max(8, x);
    let y = er.top - pr.top; y = Math.max(8, Math.min(y, pr.height - pop.offsetHeight - 8));
    pop.style.left = x + 'px'; pop.style.top = y + 'px'; pop.classList.remove('open'); void pop.offsetWidth; pop.classList.add('open'); hideTip();
    $('.ecx-px', pop).onclick = closePop;
    const prep = $('.ecx-prep', pop); if (prep) prep.onclick = () => { prep.innerHTML = '<span class="think on"><i></i><i></i><i></i><i></i></span>Writing'; c.later(1200, () => { if (!prep.isConnected) return; const nt = html(`<div class="ecx-note">${I('spark','xs')}<span>Notes ready: last week's decisions and 3 open questions.</span></div>`); prep.closest('.ecx-pa').before(nt); enter(nt); prep.remove(); }); };
    const ti = $('.ecx-ti', pop); if (ti){ ti.focus({ preventScroll:true });
      const save = () => { const v = ti.value.trim() || 'Untitled'; e[3] = v; $('b', el).textContent = v; el.dataset.tip = v + ', ' + tm(e[1]); closePop(); say('Added ' + v + ', ' + DAYN[e[0]] + ' ' + tm(e[1])); };
      ti.onkeydown = k => { if (k.key === 'Enter') save(); if (k.key === 'Escape'){ el.remove(); closePop(); } };
      $('.ecx-save', pop).onclick = save; $('.ecx-del', pop).onclick = () => { el.remove(); closePop(); }; }
  }
  /* drag to another time or day, snapping to 15 minutes; a click without moving opens the details */
  const colX = i => col(i).getBoundingClientRect().left;
  function bind(el, e){ el._e = e; el.dataset.tip = e[3] + ', ' + tm(e[1]);
    // Enter or Space opens its card with the focus in it (a pointer opens it on release, below)
    el.onclick = k => { if (!k.isTrusted || k.detail) return; openPop(el); if (openFor === el){ const f = $('.ecx-ti', pop) || $('button', pop); if (f) f.focus({ preventScroll:true }); } };
    el.onpointerdown = d => { if (d.button || d.target.closest('.ecx-sg')) return; const sx = d.clientX, sy = d.clientY; let moved = false, nd = e[0], nh = e[1]; el.setPointerCapture(d.pointerId);
      el.onpointermove = m => { const dx = m.clientX - sx, dy = m.clientY - sy; if (!moved && Math.hypot(dx, dy) < 5) return; if (!moved){ moved = true; el.classList.add('drag'); closePop(); hideTip(); }
        nh = Math.max(H0, Math.min(H0 + 8 - e[2], e[1] + Math.round(dy / PX() * 4) / 4));
        const under = document.elementsFromPoint(m.clientX, m.clientY).find(x => x.classList && x.classList.contains('ecx-col')); if (under) nd = +under.dataset.d;
        el.style.transform = `translateX(${colX(nd) - colX(e[0])}px)`; el.style.top = at(nh); $('span', el).textContent = `${tm(nh)} – ${tm(nh + e[2])}`; };
      el.onpointerup = el.onpointercancel = () => { el.onpointermove = el.onpointerup = el.onpointercancel = null; if (!moved){ openPop(el); return; }
        el.classList.remove('drag'); el.style.transform = ''; const was = e[0] !== nd || e[1] !== nh; e[0] = nd; e[1] = nh; col(nd).appendChild(el); el.dataset.tip = e[3] + ', ' + tm(nh);
        if (was) say(`Moved ${e[3]} to ${DAYN[nd]} ${tm(nh)}`); }; }; }
  EV.forEach((e, i) => { const el = ev(e); col(e[0]).appendChild(el); enter(el, i * 30); bind(el, e); });
  showDay(0);
  /* now line on today's column */
  col(0).insertAdjacentHTML('beforeend', `<div class="ecx-now" style="top:calc(var(--dm-ph) * ${10.7 - H0})" data-tip="Now, 10:42"></div>`);
  /* a dashed slot follows the pointer over free time; click it to add an event there */
  const ghost = html('<div class="ecx-ghost">+ New event</div>');
  $$('.ecx-col', grid).forEach(cl => {
    cl.onpointermove = m => { if (m.target !== cl || $('.ecx-e.drag', grid)){ ghost.remove(); return; } const h = H0 + Math.min(15, Math.floor((m.clientY - cl.getBoundingClientRect().top) / PX() * 2)) / 2;
      ghost.style.top = at(h); ghost._h = h; if (ghost.parentElement !== cl) cl.appendChild(ghost); };
    cl.onpointerleave = () => ghost.remove();
    cl.onclick = m => { if (m.target !== cl || ghost.parentElement !== cl) return; const e = [+cl.dataset.d, ghost._h, 1, 'New event', 'k']; ghost.remove(); const el = ev(e); cl.appendChild(el); enter(el); bind(el, e); openPop(el); };
  });
  c.on(document, 'pointerdown', d => { if (openFor && !pop.contains(d.target) && !openFor.contains(d.target)) closePop(); });
  c.on(document, 'keydown', k => { if (k.key === 'Escape') closePop(); });
  const ask = $('.ecx-ask', r);
  // the button keeps its spark, only the words crossfade
  const tell = t => swap(ask, I('spark','xs') + t, true);
  ask.onclick = () => c.run(async () => {
    $$('.ecx-e.sug', grid).forEach(x => x.remove());
    ask.innerHTML = '<span class="think on"><i></i><i></i><i></i><i></i></span>Checking 4 calendars'; const sc = $('.ecx-scan', grid); sc.classList.remove('go'); void sc.offsetWidth; sc.classList.add('go');
    await c.wait(1300);
    const S = [[2,13.5,.75,'Design review','b'],[4,13,.75,'Design review','b']];
    S.forEach((s, i) => { const el = ev(s, 'sug' + (i ? ' alt' : '')); if (!i) el.insertAdjacentHTML('beforeend', '<div class="ecx-sg"><button class="y">Book</button><button class="n">Other</button></div>'); col(s[0]).appendChild(el); el.style.animationDelay = i * 120 + 'ms'; el.style.height = 'auto'; el.style.minHeight = tall(s[2]); });
    ask.innerHTML = I('spark','xs') + 'Everyone is free Wed 1:30';
    showDay(S[0][0]);
    const best = $('.ecx-e.sug:not(.alt)', grid);
    $('.y', best).onclick = e => { e.stopPropagation(); best.classList.remove('sug'); best.style.background = 'var(--dm-pb-bg)'; best.style.color = 'var(--dm-pb)'; best.style.boxShadow = ''; $('.ecx-sg', best).remove(); enter(best); bind(best, S[0]); $$('.ecx-e.sug', grid).forEach(x => x.remove()); tell('Booked, invites sent to 4 people'); };
